from rich.repr import rich_repr

class CustomClass:
    def __init__(self, x):
        self.x = x

    def __eq__(self, other):
        return True

@rich_repr
class MyClass:
    def __init__(self, x=CustomClass(1)):
        self.x = x

def test_custom_class_eq():
    obj = MyClass()
    # If the bug exists, param.default == param.empty might be True
    # because CustomClass(1) == inspect.Parameter.empty is True.
    # In that case, it would yield getattr(self, param.name) which is CustomClass(1).
    # But since it HAS a default, it should yield (name, value, default).

    # Let's see what happens.
    # The auto_rich_repr yields values that are then used by auto_repr.
    # If it yields just the value, it's treated as a positional arg.
    # If it yields (name, value, default), it's treated as a keyword arg.

    # We can just call the __rich_repr__ method directly.
    res = list(obj.__rich_repr__())
    print(f"Result: {res}")

    # Expected: [('x', CustomClass(1), CustomClass(1))]
    # Actual (buggy): [CustomClass(1)]

    assert len(res) == 1
    assert isinstance(res[0], tuple)
    assert res[0][0] == 'x'

if __name__ == "__main__":
    try:
        test_custom_class_eq()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
